using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace Rabron.Prototype.Editor
{
    /// <summary>
    /// First project opening creates a tiny empty scene. All gameplay geometry
    /// is generated by PrototypeBoot on Play, so no fragile hand-authored YAML.
    /// </summary>
    [InitializeOnLoad]
    internal static class PrototypeSceneInstaller
    {
        private const string ScenePath = "Assets/Scenes/Prototype.unity";

        static PrototypeSceneInstaller()
        {
            EditorApplication.delayCall += EnsureScene;
        }

        [MenuItem("Tools/Rabron/Prepare Demo Scene")]
        private static void EnsureScene()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode ||
                EditorApplication.isCompiling || EditorApplication.isUpdating)
            {
                EditorApplication.delayCall += EnsureScene;
                return;
            }

            if (!File.Exists(ScenePath))
            {
                Directory.CreateDirectory("Assets/Scenes");
                var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,
                                                        NewSceneMode.Single);
                EditorSceneManager.SaveScene(scene, ScenePath);
                AssetDatabase.Refresh();
            }

            bool present = false;
            foreach (var buildScene in EditorBuildSettings.scenes)
                present |= buildScene.path == ScenePath && buildScene.enabled;

            if (!present)
            {
                EditorBuildSettings.scenes =
                    new[] { new EditorBuildSettingsScene(ScenePath, true) };
            }

            Scene active = EditorSceneManager.GetActiveScene();
            if (string.IsNullOrEmpty(active.path) && !active.isDirty)
                EditorSceneManager.OpenScene(ScenePath);
        }
    }
}
